      fx.usageKind = "stale"; fx.usageDelay = 1200; fx.refreshKind = "measured";
      await openUsage();
      await click(useBtn);
      await wait(`/Neu gelesen/.test(${useSec}.querySelector('.usestatus').textContent)`, 4000);
      await evaluate("new Promise(r => setTimeout(r, 1500))");
