  const slots = [alpha, { id: 2, cwd: "/fixture/beta", repo: "/fixture/beta", label: "Beta", openedAt: 2000, lastOutput: 0 },
    ...Array.from({ length: 14 }, (_, i) => ({ id: i + 3, cwd: null }))];
